                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Policy leverage"
                    domain={[40, 100]}
                    tick={{ fontSize: 11, fill: "#64748b" }}
                    label={{
                      value: "Policy leverage",
                      angle: -90,
                      position: "insideLeft",
                      fill: "#64748b",
                      fontSize: 11,
                    }}
                  />
